    public static readonly IReadOnlyList<BioSection> Sections =
    [
        new("early-life",
            new LStr(
                "Early life in Pathuria Sahi",
                "Jeunesse à Pathuria Sahi",
                "Frühe Jahre in Pathuria Sahi",
                "パトゥリア・サヒでの幼年"),
            new LStr(
                "Guru Ramakanta Mahapatra was born on 3 December 1969 in Pathuria Sahi, Puri, the neighbourhood of stoneworkers beside the Jagannath temple. His father, Damodar Mahapatra, was a sculptor, and his mother, Tukuna Devi, was a sculptor as well. He began to carve at the age of twelve, among his father, his mother and his elder brother, Padma Vibhushan Dr. Raghunath Mahapatra. The palm-leaf Silpa Sastra, the science of sculpture, stayed on the bench beside the chisel. Guru, in his case, is the honorific of a teacher.",
                "Guru Ramakanta Mahapatra est né le 3 décembre 1969 à Pathuria Sahi, Puri, le quartier des tailleurs de pierre auprès du temple de Jagannath. Son père, Damodar Mahapatra, était sculpteur, et sa mère, Tukuna Devi, l’était aussi. Il commence à tailler à douze ans, entre son père, sa mère et son frère aîné, le Dr Raghunath Mahapatra, Padma Vibhushan. Le Silpa Sastra sur feuille de palmier restait près du ciseau. Guru est ici l’honorifique du professeur.",
                "Guru Ramakanta Mahapatra wurde am 3. Dezember 1969 in Pathuria Sahi, Puri, geboren, dem Viertel der Steinmetzen am Jagannath-Tempel. Sein Vater Damodar Mahapatra war Bildhauer, seine Mutter Tukuna Devi ebenfalls. Mit zwölf begann er zu hauen, zwischen Vater, Mutter und dem älteren Bruder, Padma Vibhushan Dr. Raghunath Mahapatra. Das Silpa Sastra auf Palmblatt lag neben dem Meißel. Guru ist hier die Anrede des Lehrers.",
                "グル・ラマカンタ・マハパトラは1969年12月3日、ジャガンナート寺院に近い石工の町、プリーのパトゥリア・サヒに生まれました。父ダモーダル・マハパトラも母トゥクナ・デーヴィーも彫刻家です。十二歳で彫り始め、父と母、兄のパドマ・ヴィブーシャン、ラグナート・マハパトラ博士のなかで育ちました。貝葉のシルパ・シャーストラが鑿の傍らにありました。グルは、ここでは師への敬称です。")),
        new("lineage",
            new LStr(
                "Damodara Mahapatra and the family tradition",
                "Damodara Mahapatra et la tradition familiale",
                "Damodara Mahapatra und die Familientradition",
                "ダモーダラ・マハパトラと家の伝統"),
            new LStr(
                "Damodar Mahapatra and Tukuna Devi kept a house in which carving was a discipline of proportion, devotion and patience. Ramakanta learned to draw a sacred image, to read the grain of a block, and to finish a surface so that light would describe the form. After his father’s death he established the Damodara Mahapatra Educational and Charitable Trust, and under it he has taught boys and girls from the interior of Odisha. That inheritance is still the grammar of the atelier.",
                "Damodar Mahapatra et Tukuna Devi tenaient une maison où la taille était proportion, dévotion et patience. Ramakanta apprit à dessiner une image sacrée, à lire le fil d’un bloc, et à finir une surface pour que la lumière décrive la forme. Après la mort de son père il fonda le Damodara Mahapatra Educational and Charitable Trust, et sous ce nom il a enseigné des garçons et des filles de l’intérieur de l’Odisha.",
                "Damodar Mahapatra und Tukuna Devi führten ein Haus, in dem das Hauen Proportion, Hingabe und Geduld war. Ramakanta lernte, ein heiliges Bild zu zeichnen, das Lager eines Blocks zu lesen und eine Oberfläche so zu vollenden, dass Licht die Form beschreibt. Nach dem Tod des Vaters gründete er den Damodara Mahapatra Educational and Charitable Trust und unterrichtete darunter Jungen und Mädchen aus dem Inneren Odishas.",
                "ダモーダル・マハパトラとトゥクナ・デーヴィーの家では、彫りは比例と信仰と忍耐でした。聖像の下絵、石の目、光が形を語る仕上げを学びました。父の死後、ダモーダラ・マハパトラ教育慈善信託を立て、オディシャ内陸の少年少女を教えています。")),
        new("alongside",
            new LStr(
                "Working beside Dr. Raghunath Mahapatra",
                "Aux côtés du Dr Raghunath Mahapatra",
                "Neben Dr. Raghunath Mahapatra",
                "ラグナート・マハパトラ博士とともに"),
            new LStr(
                "At the age of twenty-four he went to Japan as associate sculptor to his elder brother, Padma Vibhushan Dr. Raghunath Mahapatra, for a fifteen-foot Ashokan pillar. The proximity clarified what mastery asks: command of iconography, the structural sense of a temple, and the willingness to let tradition speak inside a contemporary commission. He is an old student of the B.K. College of Art and Crafts, Bhubaneswar.",
                "À vingt-quatre ans il part au Japon comme sculpteur associé de son frère aîné, le Dr Raghunath Mahapatra, Padma Vibhushan, pour un pilier d’Ashoka de quinze pieds. Il est ancien élève du B.K. College of Art and Crafts, à Bhubaneswar.",
                "Mit vierundzwanzig ging er als mitarbeitender Bildhauer seines älteren Bruders, Padma Vibhushan Dr. Raghunath Mahapatra, nach Japan, für eine fünfzehn Fuß hohe Ashoka-Säule. Er ist ein früherer Student des B.K. College of Art and Crafts in Bhubaneswar.",
                "二十四歳で、兄パドマ・ヴィブーシャン、ラグナート・マハパトラ博士の助手として日本へ渡り、高さ15フィートのアショーカ石柱に携わりました。ブバネーシュワルのB・K・芸術工芸大学の出身です。")),
        new("cooperative",
            new LStr(
                "The cooperative years",
                "Les années de coopérative",
                "Die Genossenschaftsjahre",
                "協同組合の年月"),
            new LStr(
                "In 1985 he joined the Patitapabana Handicrafts Cooperative Society, and from 2002 he served as its president. In 1990 he received the State Best Designing Award from the Government of Odisha, the first state honour, recorded here as the Odisha State Award. The same year the then Chief Minister, Biju Patnaik, conferred an award for a decorative Ganesh carved in stone.",
                "En 1985 il rejoignit la Patitapabana Handicrafts Cooperative Society, et depuis 2002 il en fut le président. En 1990 il reçut le State Best Designing Award du gouvernement de l’Odisha. La même année le ministre en chef Biju Patnaik conféra un prix pour un Ganesh décoratif taillé dans la pierre.",
                "1985 trat er der Patitapabana Handicrafts Cooperative Society bei. Diese Jahre stellten die Arbeit in eine Gemeinschaft von Machern und brachten die erste öffentliche Anerkennung. 1990 erhielt er den State Best Designing Award, hier als Preis des Staates Odisha verzeichnet.",
                "1985年、パティタパバナ手工芸協同組合に加わりました。作り手の共同体のなかで仕事は公開の評価を受け、1990年に州最優秀デザイン賞（本サイトではオディシャ州賞として記します）を受けています。")),
        new("japan",
            new LStr(
                "The journey to Japan",
                "Le voyage au Japon",
                "Die Reise nach Japan",
                "日本への旅"),
            new LStr(
                "In 1995 the fifteen-foot Ashokan pillar was installed in Japan, with Ramakanta named as a main artisan beside his elder brother. In 1998 he carved for Mr. Abnor a nine-foot chain and a fifteen-foot corner in red Khandolite and green serpentine. Later work includes a Radha Krishna and a Bal Ganesh for the Ashutosh Muni Foundation at Walkers Creek Road in the United States, a Ganesha and a Navagraha sent to Italy in 2013, a Ganesha for the Pandara Ganesh Museum in Thailand, figures for a museum in Moscow, and the seven temple shrines in Singapore.",
                "En 1995 le pilier d’Ashoka de quinze pieds fut installé au Japon. En 1998 il tailla pour M. Abnor une chaîne de neuf pieds et un angle de quinze pieds en khandolite rouge et serpentine verte. Plus tard : un Radha Krishna et un Bal Ganesh pour l’Ashutosh Muni Foundation, aux États-Unis ; un Ganesha et un Navagraha envoyés en Italie en 2013 ; un Ganesha pour le musée Pandara en Thaïlande ; des figures pour un musée à Moscou ; et les sept sanctuaires de Singapour.",
                "1995 wurde eine Ashoka-Säule aus seiner Hand in Japan aufgestellt. Die Reise trug die odishanische Steinarbeit in eine andere Geografie und zeigte, dass eine Form des Subkontinents im Ausland mit Würde stehen kann. Später folgen die sieben Tempelschreine in Singapur und Installationen in Verbindung mit Italien, Thailand, Russland, den Vereinigten Staaten und Israel.",
                "1995年、彼の手によるアショーカの石柱が日本に設置されました。オディシャの石彫が別の文化地理に立ち、大陸に根ざした形が海の向こうで品位を保てることを示しました。その後、シンガポールの七つの祠堂、そしてイタリア、タイ、ロシア、米国、イスラエルに関わる設置へと広がります。")),
        new("honours",
            new LStr(
                "National recognition",
